package cz.mh.rallye.rallye_backend.competition.domain;
public final class GpsMath {
 private GpsMath(){} public static final double EARTH_RADIUS=6371008.8;
 public static void validate(double lat,double lon){if(!Double.isFinite(lat)||!Double.isFinite(lon)||StrictMath.abs(lat)>90||StrictMath.abs(lon)>180)throw new RaceEvaluator.RuleViolation("INVALID_COORDINATES");}
 public static double distance(double lat,double lon,double targetLat,double targetLon){validate(lat,lon);validate(targetLat,targetLon);double a=StrictMath.pow(StrictMath.sin(StrictMath.toRadians(targetLat-lat)/2),2)+StrictMath.cos(StrictMath.toRadians(lat))*StrictMath.cos(StrictMath.toRadians(targetLat))*StrictMath.pow(StrictMath.sin(StrictMath.toRadians(targetLon-lon)/2),2);return 2*EARTH_RADIUS*StrictMath.asin(StrictMath.sqrt(StrictMath.min(1,StrictMath.max(0,a))));}
 public static RaceEvaluator.Position outside(double lat,double lon,double radius){if(radius>=StrictMath.PI*EARTH_RADIUS)throw new RaceEvaluator.RuleViolation("GPS_OUTSIDE_POINT_UNAVAILABLE");double d=StrictMath.min(StrictMath.PI*EARTH_RADIUS,radius+StrictMath.max(10,radius*.1))/EARTH_RADIUS;for(double bearing:new double[]{0,StrictMath.PI/2,StrictMath.PI,3*StrictMath.PI/2}){double p=StrictMath.toRadians(lat),l=StrictMath.toRadians(lon);double p2=StrictMath.asin(StrictMath.sin(p)*StrictMath.cos(d)+StrictMath.cos(p)*StrictMath.sin(d)*StrictMath.cos(bearing));double l2=l+StrictMath.atan2(StrictMath.sin(bearing)*StrictMath.sin(d)*StrictMath.cos(p),StrictMath.cos(d)-StrictMath.sin(p)*StrictMath.sin(p2));double y=StrictMath.toDegrees(p2),x=((StrictMath.toDegrees(l2)+540)%360)-180;if(distance(lat,lon,y,x)>radius)return new RaceEvaluator.Position(y,x,0,false);}throw new RaceEvaluator.RuleViolation("GPS_OUTSIDE_POINT_UNAVAILABLE");}
}
